<?phpnamespace App\Http\Controllers;use App\Models\HairModel;use Illuminate\Support\Facades\Validator;use Illuminate\Http\Request;class HairController extends Controller{  public function addHairColor(Request $request)  {    $Validator = Validator::make($request->all(), [      'color_name_en' => 'required',      'color_name_es' => 'required',      'color_name_pl' => 'required'    ]);    if ($Validator->fails()) {      return response()->json(['result' => 0, 'errors' => $Validator->errors()->first()]);    }    $insert = [      'color_name_en' => $request->post('color_name_en'),      'color_name_es' => $request->post('color_name_es'),      'color_name_pl' => $request->post('color_name_pl')    ];    $result = HairModel::addHairColor($insert);    if ($result) {      return response()->json(['result' => 1, 'msg' => 'Hair Color Added Successfully', 'data' => $result]);    } else {      return response()->json(['result' => -1, 'msg' => 'Hair Color Not Added ']);    }  }  public function getAllHairColor($lang)  {    $result = HairModel::getAllHairColor($lang);    // dd($result);    if ($result) {      return response()->json(['result' => 1, 'msg' => 'Data Found', 'data' => $result]);    } else {      return response()->json(['result' => -1, 'msg' => ' No data Found']);    }  }  public function getHairColor($lang, $hair_id)  {    $result = HairModel::getHairColor($lang, $hair_id);    if ($result) {      return response()->json(['result' => 1, 'msg' => 'Data found', 'data' => $result]);    } else {      return response()->json(['result' => -1, 'msg' => 'No data Found']);    }  }  public function updateHairColor(Request $request, $hair_id)  {    $Validator = Validator::make($request->all(), [      'color_name_en' => 'required',      'color_name_es' => 'required',      'color_name_pl' => 'required'    ]);    if ($Validator->fails()) {      return response()->json(['result' => 0, 'errors' => $Validator->errors()->first()]);    }    $update = [      'color_name_en' => $request->post('color_name_en'),      'color_name_es' => $request->post('color_name_es'),      'color_name_pl' => $request->post('color_name_pl')    ];    $result = HairModel::updateHairColor($update, $hair_id);    if ($result) {      return response()->json(['result' => 1, 'msg' => 'Hair Color Updated Successfully', 'data' => $result]);    } else {      return response()->json(['result' => -1, 'msg' => 'No Changes Updated']);    }  }  public function deleteHairColor($hair_id)  {    $result = HairModel::deleteHairColor($hair_id);    if ($result) {      return response()->json(['result' => 1, 'msg' => 'Hair Color Deleted Successfully', 'data' => $result]);    } else {      return response()->json(['result' => -1, 'msg' => 'Try Again Later']);    }  }}